package server

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"regexp"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

func (s *Server) listUsers(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	q := strings.TrimSpace(r.URL.Query().Get("q"))
	if len([]rune(q)) > 200 {
		writeError(w, http.StatusBadRequest, "query_too_long", "검색어는 200자 이하여야 합니다.")
		return
	}
	page := boundedInt(r.URL.Query().Get("page"), 1, 1, 100000)
	pageSize := boundedInt(r.URL.Query().Get("pageSize"), 25, 1, 100)
	filter := ""
	args := []any{}
	if q != "" {
		filter = ` WHERE (u.username ILIKE $1 ESCAPE E'\\' OR coalesce(u.email,'') ILIKE $1 ESCAPE E'\\' OR u.display_name ILIKE $1 ESCAPE E'\\')`
		args = append(args, "%"+escapeLike(q)+"%")
	}
	var total int64
	if err := s.db.Pool.QueryRow(r.Context(), `SELECT count(*) FROM ai_admin.app_user u`+filter, args...).Scan(&total); err != nil {
		writeError(w, 500, "users_unavailable", "사용자 목록을 불러오지 못했습니다.")
		return
	}
	limitPos, offsetPos := len(args)+1, len(args)+2
	args = append(args, pageSize, (page-1)*pageSize)
	legacyUserNameProjection := `NULL::text`
	if p.HasPermission("legacy.sensitive.read") {
		if schema := s.legacySchema(r); schema != "" {
			legacyUserNameProjection = `(SELECT nullif(legacy_user.user_nm,'') FROM ` + pgx.Identifier{schema, "user_info"}.Sanitize() + ` legacy_user WHERE legacy_user.user_id::text=u.legacy_user_id::text LIMIT 1)`
		}
	}
	query := `SELECT u.id,u.username,coalesce(u.email,''),u.display_name,u.auth_source,u.status,u.legacy_user_id,u.last_login_at,u.created_at,` + legacyUserNameProjection + `,
coalesce(jsonb_agg(DISTINCT jsonb_build_object('id',r.id,'code',r.code,'name',r.name)) FILTER (WHERE r.id IS NOT NULL),'[]'::jsonb)
FROM ai_admin.app_user u LEFT JOIN ai_admin.user_role ur ON ur.user_id=u.id LEFT JOIN ai_admin.role r ON r.id=ur.role_id` + filter + `
GROUP BY u.id ORDER BY u.created_at DESC LIMIT $` + itoa(limitPos) + ` OFFSET $` + itoa(offsetPos)
	rows, err := s.db.Pool.Query(r.Context(), query, args...)
	if err != nil {
		writeError(w, 500, "users_unavailable", "사용자 목록을 불러오지 못했습니다.")
		return
	}
	defer rows.Close()
	revealedLegacyNames := 0
	items, err := collectRows(rows, func(rows pgx.Rows) (map[string]any, error) {
		var id uuid.UUID
		var legacyUserID *uuid.UUID
		var legacyUserName *string
		var username, email, name, source, status string
		var lastLogin *time.Time
		var created time.Time
		var roleRaw []byte
		var roles any
		if err := rows.Scan(&id, &username, &email, &name, &source, &status, &legacyUserID, &lastLogin, &created, &legacyUserName, &roleRaw); err != nil {
			return nil, err
		}
		_ = json.Unmarshal(roleRaw, &roles)
		item := map[string]any{"id": id, "username": username, "email": email, "displayName": name, "authSource": source, "status": status, "legacyUserId": legacyUserID, "lastLoginAt": lastLogin, "createdAt": created, "roles": roles}
		if legacyUserName != nil {
			item["legacyUserName"] = *legacyUserName
			revealedLegacyNames++
		}
		return item, nil
	})
	if err != nil {
		writeError(w, 500, "users_unavailable", "사용자 목록을 불러오지 못했습니다.")
		return
	}
	if revealedLegacyNames > 0 {
		s.audit(r, p, "legacy.sensitive.read", "user_directory_relation", "legacy_user", "success", map[string]any{"rows": revealedLegacyNames})
	}
	writePage(w, items, page, pageSize, total)
}

func (s *Server) updateUser(w http.ResponseWriter, r *http.Request) {
	id, ok := parseUUIDParameter(w, r, "id")
	if !ok {
		return
	}
	var request struct {
		DisplayName  *string  `json:"displayName"`
		Status       *string  `json:"status"`
		RoleCodes    []string `json:"roleCodes"`
		LegacyUserID *string  `json:"legacyUserId"`
	}
	if !decodeJSON(w, r, &request) {
		return
	}
	if request.Status != nil && *request.Status != "active" && *request.Status != "locked" && *request.Status != "disabled" {
		writeError(w, 400, "status_invalid", "사용자 상태가 올바르지 않습니다.")
		return
	}
	if request.DisplayName != nil {
		value := strings.TrimSpace(*request.DisplayName)
		if value == "" || utf8.RuneCountInString(value) > 190 {
			writeError(w, 400, "name_invalid", "표시 이름이 올바르지 않습니다.")
			return
		}
		request.DisplayName = &value
	}
	p := principalFrom(r.Context())
	var legacyUserID any
	if request.LegacyUserID != nil {
		if !p.HasPermission("roles.manage") {
			writeError(w, http.StatusForbidden, "permission_denied", "레거시 사용자 연결을 변경하려면 역할·권한 관리 권한이 필요합니다.")
			return
		}
		value := strings.TrimSpace(*request.LegacyUserID)
		if value != "" {
			parsed, err := uuid.Parse(value)
			if err != nil {
				writeError(w, 400, "legacy_user_invalid", "레거시 사용자 ID가 올바른 UUID가 아닙니다.")
				return
			}
			schema := s.legacySchema(r)
			var exists bool
			query := `SELECT EXISTS(SELECT 1 FROM ` + pgx.Identifier{schema, "user_info"}.Sanitize() + ` WHERE user_id=$1)`
			if err := s.db.Pool.QueryRow(r.Context(), query, parsed).Scan(&exists); err != nil || !exists {
				writeError(w, 400, "legacy_user_invalid", "레거시 user_info에서 해당 사용자를 찾을 수 없습니다.")
				return
			}
			legacyUserID = parsed
		}
	}
	if request.RoleCodes != nil && !p.HasPermission("roles.manage") {
		writeError(w, http.StatusForbidden, "permission_denied", "사용자 역할을 변경하려면 역할·권한 관리 권한이 필요합니다.")
		return
	}
	if request.RoleCodes != nil {
		request.RoleCodes = uniqueStrings(request.RoleCodes)
	}
	if id == p.ID && request.Status != nil && *request.Status != "active" {
		writeError(w, 409, "self_disable_denied", "현재 로그인한 본인 계정은 비활성화할 수 없습니다.")
		return
	}
	tx, err := s.db.Pool.Begin(r.Context())
	if err != nil {
		writeError(w, 500, "user_update_failed", "사용자를 저장하지 못했습니다.")
		return
	}
	defer func() { _ = tx.Rollback(r.Context()) }()
	changesSuperAdminState := request.RoleCodes != nil || request.Status != nil
	if changesSuperAdminState {
		// Every role/status update participates in the same serialization point.
		// Checking the target before taking this lock lets a concurrent grant turn
		// a previously ordinary user into the last super administrator immediately
		// before this transaction deletes that newly granted role.
		if _, err := tx.Exec(r.Context(), `SELECT pg_advisory_xact_lock(hashtextextended('ai_admin.last_super_admin',0))`); err != nil {
			writeError(w, 500, "user_update_failed", "서비스 관리자 상태를 잠그지 못했습니다.")
			return
		}
	}
	var isSuperAdmin bool
	if err := tx.QueryRow(r.Context(), `SELECT EXISTS(
SELECT 1 FROM ai_admin.user_role ur JOIN ai_admin.role r ON r.id=ur.role_id
WHERE ur.user_id=$1 AND r.code='super_admin')`, id).Scan(&isSuperAdmin); err != nil {
		writeError(w, 500, "user_update_failed", "사용자 역할을 확인하지 못했습니다.")
		return
	}
	removesSuperAdmin := isSuperAdmin && ((request.Status != nil && *request.Status != "active") || (request.RoleCodes != nil && !containsString(request.RoleCodes, "super_admin")))
	if removesSuperAdmin {
		var activeSuperAdmins int
		if err := tx.QueryRow(r.Context(), `SELECT count(DISTINCT u.id) FROM ai_admin.app_user u
JOIN ai_admin.user_role ur ON ur.user_id=u.id JOIN ai_admin.role role ON role.id=ur.role_id
WHERE role.code='super_admin' AND u.status='active'`).Scan(&activeSuperAdmins); err != nil {
			writeError(w, 500, "user_update_failed", "서비스 관리자 수를 확인하지 못했습니다.")
			return
		}
		if activeSuperAdmins <= 1 {
			writeError(w, 409, "last_super_admin", "마지막 활성 서비스 관리자 권한은 제거하거나 비활성화할 수 없습니다.")
			return
		}
	}
	result, err := tx.Exec(r.Context(), `UPDATE ai_admin.app_user SET display_name=coalesce($2,display_name),status=coalesce($3,status),
legacy_user_id=CASE WHEN $4::boolean THEN $5::uuid ELSE legacy_user_id END,updated_at=now() WHERE id=$1`, id, request.DisplayName, request.Status, request.LegacyUserID != nil, legacyUserID)
	if err != nil {
		var databaseError *pgconn.PgError
		if errors.As(err, &databaseError) && databaseError.Code == "23505" {
			writeError(w, http.StatusConflict, "legacy_user_conflict", "이미 다른 계정에 연결된 레거시 사용자입니다.")
			return
		}
		writeError(w, 500, "user_update_failed", "사용자를 저장하지 못했습니다.")
		return
	}
	if result.RowsAffected() == 0 {
		writeError(w, 404, "user_not_found", "사용자를 찾을 수 없습니다.")
		return
	}
	if request.RoleCodes != nil {
		var roleCount int
		if err := tx.QueryRow(r.Context(), `SELECT count(*) FROM ai_admin.role WHERE code=ANY($1)`, request.RoleCodes).Scan(&roleCount); err != nil {
			writeError(w, 500, "user_update_failed", "역할 목록을 확인하지 못했습니다.")
			return
		} else if roleCount != len(request.RoleCodes) {
			writeError(w, 400, "roles_invalid", "존재하지 않는 역할이 포함되어 있습니다.")
			return
		}
		if _, err = tx.Exec(r.Context(), `DELETE FROM ai_admin.user_role WHERE user_id=$1`, id); err != nil {
			writeError(w, 500, "user_update_failed", "기존 사용자 역할을 정리하지 못했습니다.")
			return
		}
		if len(request.RoleCodes) > 0 {
			if _, err = tx.Exec(r.Context(), `INSERT INTO ai_admin.user_role(user_id,role_id) SELECT $1,id FROM ai_admin.role WHERE code=ANY($2)`, id, request.RoleCodes); err != nil {
				writeError(w, 500, "user_update_failed", "새 사용자 역할을 저장하지 못했습니다.")
				return
			}
		}
	}
	if err := tx.Commit(r.Context()); err != nil {
		writeError(w, 500, "user_update_failed", "사용자를 저장하지 못했습니다.")
		return
	}
	s.audit(r, p, "user.update", "app_user", id.String(), "success", map[string]any{"roles": request.RoleCodes})
	writeData(w, 200, map[string]bool{"updated": true})
}

func (s *Server) listRoles(w http.ResponseWriter, r *http.Request) {
	rows, err := s.db.Pool.Query(r.Context(), `SELECT r.id,r.code,r.name,coalesce(r.description,''),r.system_role,r.created_at,r.updated_at,
coalesce(jsonb_agg(rp.permission_code ORDER BY rp.permission_code) FILTER(WHERE rp.permission_code IS NOT NULL),'[]'::jsonb)
FROM ai_admin.role r LEFT JOIN ai_admin.role_permission rp ON rp.role_id=r.id GROUP BY r.id ORDER BY r.system_role DESC,r.name`)
	if err != nil {
		writeError(w, 500, "roles_unavailable", "역할 목록을 불러오지 못했습니다.")
		return
	}
	defer rows.Close()
	items, err := collectRows(rows, func(rows pgx.Rows) (map[string]any, error) {
		var id uuid.UUID
		var code, name, desc string
		var system bool
		var created, updated time.Time
		var raw []byte
		var perms any
		if err := rows.Scan(&id, &code, &name, &desc, &system, &created, &updated, &raw); err != nil {
			return nil, err
		}
		_ = json.Unmarshal(raw, &perms)
		return map[string]any{"id": id, "code": code, "name": name, "description": desc, "systemRole": system, "permissions": perms, "createdAt": created, "updatedAt": updated}, nil
	})
	if err != nil {
		writeError(w, 500, "roles_unavailable", "역할 목록을 불러오지 못했습니다.")
		return
	}
	writeData(w, 200, items)
}

func (s *Server) updateRole(w http.ResponseWriter, r *http.Request) {
	id, ok := parseUUIDParameter(w, r, "id")
	if !ok {
		return
	}
	var request struct {
		Name            *string  `json:"name"`
		Description     *string  `json:"description"`
		PermissionCodes []string `json:"permissionCodes"`
	}
	if !decodeJSON(w, r, &request) {
		return
	}
	if request.PermissionCodes != nil {
		request.PermissionCodes = uniqueStrings(request.PermissionCodes)
	}
	var code string
	if err := s.db.Pool.QueryRow(r.Context(), `SELECT code FROM ai_admin.role WHERE id=$1`, id).Scan(&code); errors.Is(err, pgx.ErrNoRows) {
		writeError(w, 404, "role_not_found", "역할을 찾을 수 없습니다.")
		return
	} else if err != nil {
		writeError(w, 500, "role_update_failed", "역할을 확인하지 못했습니다.")
		return
	}
	if code == "super_admin" {
		writeError(w, 409, "system_role_locked", "서비스 관리자 역할은 전체 권한을 유지해야 합니다.")
		return
	}
	tx, err := s.db.Pool.Begin(r.Context())
	if err != nil {
		writeError(w, 500, "role_update_failed", "역할을 저장하지 못했습니다.")
		return
	}
	defer func() { _ = tx.Rollback(r.Context()) }()
	if _, err = tx.Exec(r.Context(), `UPDATE ai_admin.role SET name=coalesce($2,name),description=coalesce($3,description),updated_at=now() WHERE id=$1`, id, request.Name, request.Description); err != nil {
		writeError(w, 500, "role_update_failed", "역할을 저장하지 못했습니다.")
		return
	}
	if request.PermissionCodes != nil {
		var count int
		if err = tx.QueryRow(r.Context(), `SELECT count(*) FROM ai_admin.permission WHERE code=ANY($1)`, request.PermissionCodes).Scan(&count); err != nil {
			writeError(w, 500, "role_update_failed", "권한 목록을 확인하지 못했습니다.")
			return
		} else if count != len(request.PermissionCodes) {
			writeError(w, 400, "permissions_invalid", "존재하지 않는 권한이 포함되어 있습니다.")
			return
		}
		if _, err = tx.Exec(r.Context(), `DELETE FROM ai_admin.role_permission WHERE role_id=$1`, id); err != nil {
			writeError(w, 500, "role_update_failed", "기존 역할 권한을 정리하지 못했습니다.")
			return
		}
		if len(request.PermissionCodes) > 0 {
			_, err = tx.Exec(r.Context(), `INSERT INTO ai_admin.role_permission(role_id,permission_code) SELECT $1,unnest($2::text[])`, id, request.PermissionCodes)
		}
	}
	if err != nil || tx.Commit(r.Context()) != nil {
		writeError(w, 500, "role_update_failed", "역할을 저장하지 못했습니다.")
		return
	}
	p := principalFrom(r.Context())
	s.audit(r, p, "role.update", "role", id.String(), "success", map[string]any{"permissions": request.PermissionCodes})
	writeData(w, 200, map[string]bool{"updated": true})
}

func (s *Server) listPermissions(w http.ResponseWriter, r *http.Request) {
	rows, err := s.db.Pool.Query(r.Context(), `SELECT code,name,category,coalesce(description,'') FROM ai_admin.permission ORDER BY category,code`)
	if err != nil {
		writeError(w, 500, "permissions_unavailable", "권한 목록을 불러오지 못했습니다.")
		return
	}
	defer rows.Close()
	items, err := collectRows(rows, func(rows pgx.Rows) (map[string]any, error) {
		var code, name, category, desc string
		if err := rows.Scan(&code, &name, &category, &desc); err != nil {
			return nil, err
		}
		return map[string]any{"code": code, "name": name, "category": category, "description": desc}, nil
	})
	if err != nil {
		writeError(w, 500, "permissions_unavailable", "권한 목록을 불러오지 못했습니다.")
		return
	}
	writeData(w, 200, items)
}

func (s *Server) listSessions(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	if p.AuthMethod == "api_key" && !p.HasScope("profile:read") {
		writeError(w, 403, "scope_denied", "API 키에 profile:read scope가 없습니다.")
		return
	}
	rows, err := s.db.Pool.Query(r.Context(), `SELECT id_hash,host(coalesce(ip_address,'0.0.0.0'::inet)),coalesce(user_agent,''),expires_at,last_seen_at,created_at,revoked_at FROM ai_admin.session WHERE user_id=$1 ORDER BY created_at DESC`, p.ID)
	if err != nil {
		writeError(w, 500, "sessions_unavailable", "세션 목록을 불러오지 못했습니다.")
		return
	}
	defer rows.Close()
	items, err := collectRows(rows, func(rows pgx.Rows) (map[string]any, error) {
		var hash, ip, ua string
		var expires, lastSeen, created time.Time
		var revoked *time.Time
		if err := rows.Scan(&hash, &ip, &ua, &expires, &lastSeen, &created, &revoked); err != nil {
			return nil, err
		}
		return map[string]any{"id": hash[:12], "ipAddress": ip, "userAgent": ua, "expiresAt": expires, "lastSeenAt": lastSeen, "createdAt": created, "revokedAt": revoked, "current": hash == p.SessionHash}, nil
	})
	if err != nil {
		writeError(w, 500, "sessions_unavailable", "세션 목록을 불러오지 못했습니다.")
		return
	}
	writeData(w, 200, items)
}

func (s *Server) revokeOtherSessions(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	if err := s.auth.RevokeAllOtherSessions(r.Context(), p.ID, p.SessionHash); err != nil {
		writeError(w, 500, "session_revoke_failed", "다른 세션을 종료하지 못했습니다.")
		return
	}
	s.audit(r, p, "session.revoke_others", "session", "", "success", nil)
	writeData(w, 200, map[string]bool{"revoked": true})
}

func (s *Server) revokeSession(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	prefix := strings.TrimSpace(chiURLParam(r, "id"))
	if len(prefix) != 12 || !regexp.MustCompile(`^[0-9a-f]{12}$`).MatchString(prefix) {
		writeError(w, 400, "session_id_invalid", "세션 ID가 올바르지 않습니다.")
		return
	}
	result, err := s.db.Pool.Exec(r.Context(), `UPDATE ai_admin.session SET revoked_at=coalesce(revoked_at,now()) WHERE user_id=$1 AND id_hash LIKE $2 AND id_hash<>$3 AND revoked_at IS NULL`, p.ID, prefix+"%", p.SessionHash)
	if err != nil {
		writeError(w, 500, "session_revoke_failed", "세션을 종료하지 못했습니다.")
		return
	}
	if result.RowsAffected() == 0 {
		writeError(w, 404, "session_not_found", "종료할 다른 세션을 찾을 수 없습니다.")
		return
	}
	s.audit(r, p, "session.revoke", "session", prefix, "success", nil)
	writeData(w, 200, map[string]bool{"revoked": true})
}

func (s *Server) updateProfile(w http.ResponseWriter, r *http.Request) {
	var request struct {
		DisplayName string  `json:"displayName"`
		Email       *string `json:"email"`
		Department  *string `json:"department"`
	}
	if !decodeJSON(w, r, &request) {
		return
	}
	request.DisplayName = strings.TrimSpace(request.DisplayName)
	if request.DisplayName == "" || utf8.RuneCountInString(request.DisplayName) > 190 {
		writeError(w, 400, "profile_invalid", "표시 이름은 1~190자여야 합니다.")
		return
	}
	p := principalFrom(r.Context())
	var email any
	emailSupplied := request.Email != nil
	if p.AuthSource == "local" && request.Email != nil {
		value := strings.TrimSpace(*request.Email)
		if value != "" && (!strings.Contains(value, "@") || utf8.RuneCountInString(value) > 320) {
			writeError(w, 400, "email_invalid", "이메일 형식이 올바르지 않습니다.")
			return
		}
		if value != "" {
			email = value
		}
	}
	result, err := s.db.Pool.Exec(r.Context(), `UPDATE ai_admin.app_user SET display_name=$2,
email=CASE WHEN auth_source='local' AND $4::boolean THEN $3::varchar ELSE email END,updated_at=now() WHERE id=$1`, p.ID, request.DisplayName, email, emailSupplied)
	if err != nil {
		var databaseError *pgconn.PgError
		if errors.As(err, &databaseError) && databaseError.Code == "23505" {
			writeError(w, http.StatusConflict, "email_conflict", "이미 다른 계정이 사용 중인 이메일입니다.")
			return
		}
		writeError(w, 500, "profile_update_failed", "프로필을 저장하지 못했습니다.")
		return
	}
	if result.RowsAffected() == 0 {
		writeError(w, 404, "user_not_found", "사용자를 찾을 수 없습니다.")
		return
	}
	s.audit(r, p, "profile.update", "app_user", p.ID.String(), "success", nil)
	writeData(w, 200, map[string]bool{"updated": true})
}

func (s *Server) getPreferences(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	if p.AuthMethod == "api_key" && !p.HasScope("profile:read") {
		writeError(w, 403, "scope_denied", "API 키에 profile:read scope가 없습니다.")
		return
	}
	current, err := s.loadPreferences(r.Context(), p.ID)
	if err != nil {
		writeError(w, 500, "preferences_unavailable", "개인 설정을 불러오지 못했습니다.")
		return
	}
	sidebarValue := objectValue(current.sidebar)
	notifications := objectValue(current.notifications)
	writeData(w, 200, map[string]any{
		"theme": current.theme, "locale": current.locale, "language": strings.Split(current.locale, "-")[0], "timezone": current.timezone,
		"fontScale": current.fontScale, "sidebarState": sidebarValue, "aiDefaults": decodeRaw(current.aiDefaults),
		"compactTables": sidebarValue["compactTables"], "emailNotifications": notifications["email"], "approvalNotifications": notifications["approval"],
	})
}

func (s *Server) updatePreferences(w http.ResponseWriter, r *http.Request) {
	var request struct {
		Theme                 *string         `json:"theme"`
		Locale                *string         `json:"locale"`
		Language              *string         `json:"language"`
		Timezone              *string         `json:"timezone"`
		FontScale             *float64        `json:"fontScale"`
		SidebarState          json.RawMessage `json:"sidebarState"`
		AIDefaults            json.RawMessage `json:"aiDefaults"`
		CompactTables         *bool           `json:"compactTables"`
		EmailNotifications    *bool           `json:"emailNotifications"`
		ApprovalNotifications *bool           `json:"approvalNotifications"`
	}
	if !decodeJSON(w, r, &request) {
		return
	}
	if request.Theme != nil && *request.Theme != "light" && *request.Theme != "dark" && *request.Theme != "system" {
		writeError(w, 400, "theme_invalid", "테마가 올바르지 않습니다.")
		return
	}
	if request.FontScale != nil && (*request.FontScale < .9 || *request.FontScale > 1.3) {
		writeError(w, 400, "font_scale_invalid", "글자 배율은 0.9~1.3 사이여야 합니다.")
		return
	}
	if value := optionalTrimmed(request.Locale); value != "" && !validPreferenceLocale(value) {
		writeError(w, 400, "locale_invalid", "언어 태그가 올바르지 않습니다.")
		return
	}
	if value := optionalTrimmed(request.Timezone); value != "" && !validPreferenceTimezone(value) {
		writeError(w, 400, "timezone_invalid", "시간대가 올바르지 않습니다.")
		return
	}
	p := principalFrom(r.Context())
	current, err := s.loadPreferences(r.Context(), p.ID)
	if err != nil {
		writeError(w, 500, "preferences_update_failed", "개인 설정을 불러오지 못했습니다.")
		return
	}
	theme, locale, timezone, scale := current.theme, current.locale, current.timezone, current.fontScale
	if request.Theme != nil {
		theme = *request.Theme
	}
	if value := optionalTrimmed(request.Locale); value != "" {
		locale = value
	}
	if request.Language != nil && *request.Language == "ko" {
		locale = "ko-KR"
	}
	if value := optionalTrimmed(request.Timezone); value != "" {
		timezone = value
	}
	if request.FontScale != nil {
		scale = *request.FontScale
	}
	sidebar := objectValue(current.sidebar)
	if len(request.SidebarState) > 0 {
		sidebar = objectValue(request.SidebarState)
	}
	if request.CompactTables != nil {
		sidebar["compactTables"] = *request.CompactTables
	}
	aiRaw := current.aiDefaults
	if len(request.AIDefaults) > 0 {
		aiRaw = request.AIDefaults
	}
	notifications := objectValue(current.notifications)
	if request.EmailNotifications != nil {
		notifications["email"] = *request.EmailNotifications
	}
	if request.ApprovalNotifications != nil {
		notifications["approval"] = *request.ApprovalNotifications
	}
	sidebarJSON, _ := json.Marshal(sidebar)
	notificationsJSON, _ := json.Marshal(notifications)
	// The preference row is created on the first save rather than assumed to
	// exist: an account provisioned straight into app_user has no row yet, and
	// an UPDATE would then discard the settings while reporting success.
	_, err = s.db.Pool.Exec(r.Context(), `INSERT INTO ai_admin.user_preference(user_id,theme,locale,timezone,font_scale,sidebar_state,ai_defaults,notification_preferences)
VALUES($1,$2,$3,$4,$5,$6::jsonb,$7::jsonb,$8::jsonb)
ON CONFLICT(user_id) DO UPDATE SET theme=excluded.theme,locale=excluded.locale,timezone=excluded.timezone,font_scale=excluded.font_scale,
sidebar_state=excluded.sidebar_state,ai_defaults=excluded.ai_defaults,notification_preferences=excluded.notification_preferences,updated_at=now()`,
		p.ID, theme, locale, timezone, scale, sidebarJSON, aiRaw, notificationsJSON)
	if err != nil {
		writeError(w, 500, "preferences_update_failed", "개인 설정을 저장하지 못했습니다.")
		return
	}
	writeData(w, 200, map[string]bool{"updated": true})
}

// locale·timezone은 varchar(20)·varchar(80) column에 그대로 들어간다. 상한을 넘는
// 값이나 형식에 맞지 않는 값을 그대로 upsert하면 DB가 거부해 400이어야 할 요청이
// 500 preferences_update_failed가 되고, 같은 요청에 담긴 다른 설정 변경까지 함께
// 사라진다. 저장할 수 있는 형식만 받아 저장소가 아니라 요청을 탓하게 한다.
var (
	preferenceLocalePattern   = regexp.MustCompile(`^[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*$`)
	preferenceTimezonePattern = regexp.MustCompile(`^[A-Za-z0-9._+-]+(/[A-Za-z0-9._+-]+)*$`)
)

func validPreferenceLocale(value string) bool {
	return utf8.RuneCountInString(value) <= 20 && preferenceLocalePattern.MatchString(value)
}

func validPreferenceTimezone(value string) bool {
	return utf8.RuneCountInString(value) <= 80 && preferenceTimezonePattern.MatchString(value)
}

func optionalTrimmed(value *string) string {
	if value == nil {
		return ""
	}
	return strings.TrimSpace(*value)
}

type userPreferences struct {
	theme         string
	locale        string
	timezone      string
	fontScale     float64
	sidebar       []byte
	aiDefaults    []byte
	notifications []byte
}

func defaultPreferences() userPreferences {
	return userPreferences{
		theme: "system", locale: "ko-KR", timezone: "Asia/Seoul", fontScale: 1,
		sidebar: []byte(`{}`), aiDefaults: []byte(`{}`), notifications: []byte(`{"email":true,"approval":true}`),
	}
}

// loadPreferences reads the stored settings of one account. A missing row means
// the account has never saved anything, which is the column defaults rather
// than a failure; only a query error is reported as one.
func (s *Server) loadPreferences(ctx context.Context, userID uuid.UUID) (userPreferences, error) {
	current := defaultPreferences()
	err := s.db.Pool.QueryRow(ctx, `SELECT theme,locale,timezone,font_scale::float8,sidebar_state,ai_defaults,notification_preferences FROM ai_admin.user_preference WHERE user_id=$1`, userID).Scan(
		&current.theme, &current.locale, &current.timezone, &current.fontScale, &current.sidebar, &current.aiDefaults, &current.notifications)
	if errors.Is(err, pgx.ErrNoRows) {
		return defaultPreferences(), nil
	}
	if err != nil {
		return userPreferences{}, err
	}
	return current, nil
}

func objectValue(raw []byte) map[string]any {
	value := map[string]any{}
	_ = json.Unmarshal(raw, &value)
	return value
}

func containsString(values []string, expected string) bool {
	for _, value := range values {
		if value == expected {
			return true
		}
	}
	return false
}

func itoa(value int) string { return strconv.Itoa(value) }
package server

import (
	"bytes"
	"context"
	"io"
	"log/slog"
	"net/http"
	"net/url"
	"os"
	"strings"
	"testing"

	"github.com/google/uuid"
	"github.com/hkjang/ai-admin/internal/database"
	"github.com/hkjang/ai-admin/internal/secrets"
)

// The user directory search shares the 200-character contract of the audit,
// legacy and MCP searches: anything longer is refused before it reaches the
// three-column ILIKE scan. The limit counts characters, not bytes, because the
// SPA sends Korean search terms.
func TestListUsersRejectsOverlongQuery(t *testing.T) {
	dsn := os.Getenv("TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("TEST_POSTGRES_DSN is not set")
	}

	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE; DROP SCHEMA IF EXISTS aiportal CASCADE`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	cipher, err := secrets.New(bytes.Repeat([]byte{7}, 32))
	if err != nil {
		t.Fatal(err)
	}
	handler := New(db, cipher, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()
	admin := signIn(t, handler)

	// Hangul is three bytes per character: a byte-based limit would wrongly
	// refuse these terms. display_name is varchar(190), so the longest name
	// that can exist is searched with itself and the 200-character term must
	// still reach the database and come back as an empty page.
	longestName := strings.Repeat("가", 190)
	exactLimit := strings.Repeat("가", 200)
	if _, err := db.Pool.Exec(ctx, `INSERT INTO ai_admin.app_user(id,username,display_name,auth_source,status)
VALUES($1,'long-name@example.com',$2,'local','active')`, uuid.New(), longestName); err != nil {
		t.Fatal(err)
	}
	list := func(q string) *http.Response {
		t.Helper()
		return admin.do(t, handler, http.MethodGet, "/api/v1/users?page=1&pageSize=25&q="+url.QueryEscape(q), nil).Result()
	}

	response := list(longestName)
	if response.StatusCode != http.StatusOK {
		t.Fatalf("190-character query status=%d body=%s", response.StatusCode, readBody(response))
	}
	var envelope legacyHTTPPage
	decodeResponse(t, response, &envelope)
	if envelope.Page.Total != 1 || len(envelope.Data) != 1 || envelope.Data[0]["username"] != "long-name@example.com" {
		t.Fatalf("190-character query did not return the matching user: %#v", envelope)
	}
	response = list(exactLimit)
	if response.StatusCode != http.StatusOK {
		t.Fatalf("200-character query status=%d body=%s", response.StatusCode, readBody(response))
	}
	decodeResponse(t, response, &envelope)
	if envelope.Page.Total != 0 || len(envelope.Data) != 0 {
		t.Fatalf("200-character query should have searched and found nobody: %#v", envelope)
	}

	overlong := list(exactLimit + "가")
	if overlong.StatusCode != http.StatusBadRequest {
		t.Fatalf("201-character query status=%d body=%s", overlong.StatusCode, readBody(overlong))
	}
	var failure struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	decodeResponse(t, overlong, &failure)
	if failure.Error.Code != "query_too_long" || failure.Error.Message != "검색어는 200자 이하여야 합니다." {
		t.Fatalf("201-character query error=%+v", failure.Error)
	}

	// Surrounding whitespace is trimmed before the limit is applied, and an
	// empty or absent q still lists everyone.
	padded := list("   " + exactLimit + "   ")
	if padded.StatusCode != http.StatusOK {
		t.Fatalf("padded 200-character query status=%d body=%s", padded.StatusCode, readBody(padded))
	}
	all := list("")
	if all.StatusCode != http.StatusOK {
		t.Fatalf("empty query status=%d body=%s", all.StatusCode, readBody(all))
	}
	decodeResponse(t, all, &envelope)
	if envelope.Page.Total != 2 {
		t.Fatalf("empty query total=%d want=2", envelope.Page.Total)
	}
}
name: CI

on:
  push:
    branches: [main]
  pull_request:

permissions:
  contents: read

jobs:
  # 테스트가 잡지 못하는 회귀를 빠르게 되돌려 보낸다. 데이터베이스도 컨테이너도
  # 필요 없으므로 test job과 나란히 돌며 몇 분 안에 결과를 낸다.
  lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4.4.0
      - uses: actions/setup-go@40f1582b2485089dde7abd97c1529aa768e1baff # v5.6.0
        with:
          go-version: "1.26.6"
          cache: true
      - name: gofmt
        run: |
          unformatted=$(gofmt -l .)
          if [ -n "$unformatted" ]; then
            echo "::error::gofmt로 정리되지 않은 파일이 있습니다"
            echo "$unformatted"
            exit 1
          fi
      - name: go vet
        run: go vet ./...
      - name: Version metadata
        run: ./scripts/verify-version.sh

  test:
    runs-on: ubuntu-latest
    services:
      postgres:
        image: postgres:16-alpine@sha256:cf78e76683b9ca8c5733cbbdce6c9262b45b6767934dd0a95e671f9a0fc20685
        env:
          POSTGRES_USER: ai_admin
          POSTGRES_PASSWORD: test-password
          POSTGRES_DB: ai_admin_test
        ports: ["5432:5432"]
        options: >-
          --health-cmd "pg_isready -U ai_admin -d ai_admin_test"
          --health-interval 5s --health-timeout 5s --health-retries 10
    steps:
      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4.4.0
      - uses: actions/setup-go@40f1582b2485089dde7abd97c1529aa768e1baff # v5.6.0
        with:
          go-version: "1.26.6"
          cache: true
      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0
        with:
          node-version: 26
          cache: npm
          cache-dependency-path: web/package-lock.json
      - name: Start Keycloak OIDC E2E
        shell: bash
        run: |
          set -euo pipefail
          docker run --detach --rm --name ai-admin-keycloak-e2e \
            --publish 127.0.0.1:18080:8080 \
            --volume "${{ github.workspace }}/internal/server/testdata/keycloak-e2e-realm.json:/opt/keycloak/data/import/ai-admin-e2e-realm.json:ro" \
            --env KC_BOOTSTRAP_ADMIN_USERNAME=admin \
            --env KC_BOOTSTRAP_ADMIN_PASSWORD=integration-password \
            quay.io/keycloak/keycloak:26.7.2@sha256:9d1f1b2b7261ff53c66cb1092dfcdc34a5fb77e81f9e6a6e75b8b6a795de8067 \
            start-dev --import-realm
          for attempt in $(seq 1 90); do
            if curl --fail --silent --show-error \
              http://127.0.0.1:18080/realms/ai-admin-e2e/.well-known/openid-configuration >/dev/null; then
              exit 0
            fi
            sleep 2
          done
          docker logs ai-admin-keycloak-e2e
          exit 1
      - name: Go tests
        run: go test -race ./...
        env:
          TEST_POSTGRES_DSN: postgres://ai_admin:test-password@localhost:5432/ai_admin_test?sslmode=disable
          TEST_KEYCLOAK_ISSUER: http://127.0.0.1:18080/realms/ai-admin-e2e
      - name: Stop Keycloak OIDC E2E
        if: always()
        run: docker stop ai-admin-keycloak-e2e || true
      - run: npm ci && npm test && npm run build
        working-directory: web
      - run: docker build --pull --build-arg VERSION=v$(cat VERSION) --tag ai-admin:ci .
name: Deploy GitHub Pages

on:
  push:
    branches: [main]
    paths: ["docs/**", ".github/workflows/pages.yml"]
  workflow_dispatch:

permissions:
  contents: read
  pages: write
  id-token: write

concurrency:
  group: pages
  cancel-in-progress: true

jobs:
  deploy:
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4.4.0
      - name: Validate referenced screenshots
        shell: bash
        run: |
          python3 - <<'PY'
          from html.parser import HTMLParser
          from pathlib import Path, PurePosixPath
          import re

          class ScreenshotReferences(HTMLParser):
              def __init__(self):
                  super().__init__()
                  self.paths = []

              def handle_starttag(self, tag, attrs):
                  if tag != "object":
                      return
                  attributes = dict(attrs)
                  data = attributes.get("data", "")
                  if data.startswith("screenshots/") and data.endswith(".webp"):
                      self.paths.append(data)

          parser = ScreenshotReferences()
          parser.feed(Path("docs/index.html").read_text(encoding="utf-8"))
          if len(parser.paths) != 44 or len(set(parser.paths)) != 44:
              raise SystemExit(
                  f"docs/index.html must reference 44 unique WebP screenshots; "
                  f"found {len(parser.paths)} references and {len(set(parser.paths))} unique paths"
              )

          referenced = set(parser.paths)
          actual = {
              f"screenshots/{path.name}"
              for path in Path("docs/screenshots").glob("*.webp")
          }
          if actual != referenced:
              raise SystemExit(
                  "docs/screenshots WebP set must exactly match docs/index.html; "
                  f"missing={sorted(referenced - actual)}, extra={sorted(actual - referenced)}"
              )

          readme = Path("docs/screenshots/README.md").read_text(encoding="utf-8")
          documented = {
              f"screenshots/{name}"
              for name in re.findall(r"^\| `([^`]+\.webp)` \|", readme, flags=re.MULTILINE)
          }
          if documented != referenced:
              raise SystemExit(
                  "docs/screenshots/README.md set must exactly match docs/index.html; "
                  f"missing={sorted(referenced - documented)}, extra={sorted(documented - referenced)}"
              )

          capture_source = Path("scripts/capture-screenshots.mjs").read_text(encoding="utf-8")
          captured = {"screenshots/login.webp", "screenshots/mobile.webp"} | {
              f"screenshots/{name}"
              for name in re.findall(r"\{ file: '([^']+\.webp)'", capture_source)
          }
          if captured != referenced:
              raise SystemExit(
                  "capture script set must exactly match docs/index.html; "
                  f"missing={sorted(referenced - captured)}, extra={sorted(captured - referenced)}"
              )

          for relative in parser.paths:
              path_parts = PurePosixPath(relative).parts
              if len(path_parts) != 2 or path_parts[0] != "screenshots":
                  raise SystemExit(f"Unsafe screenshot path in docs/index.html: {relative}")
              path = Path("docs") / relative
              if not path.is_file() or path.stat().st_size < 12:
                  raise SystemExit(f"Missing or empty screenshot: {path}")
              with path.open("rb") as screenshot:
                  header = screenshot.read(12)
              if header[:4] != b"RIFF" or header[8:12] != b"WEBP":
                  raise SystemExit(f"Invalid RIFF/WEBP signature: {path}")

          print("Validated exact 44-file screenshot set across index, directory, README, and capture script")
          PY
      - uses: actions/configure-pages@983d7736d9b0ae728b81ab479565c72886d7745b # v5.0.0
      - uses: actions/upload-pages-artifact@56afc609e74202658d3ffba0e8f6dda462b719fa # v3.0.1
        with:
          path: docs
      - name: Deploy
        id: deployment
        uses: actions/deploy-pages@d6db90164ac5ed86f2b6aed7e0febac5b3c0c03e # v4.0.5
name: Offline release

on:
  push:
    tags: ["v*"]
  workflow_dispatch:
    inputs:
      version_tag:
        description: Existing release tag matching VERSION (for example, v1.0.0)
        required: true
        type: string

permissions:
  contents: write

jobs:
  release:
    runs-on: ubuntu-latest
    env:
      RELEASE_TAG: ${{ github.event_name == 'workflow_dispatch' && inputs.version_tag || github.ref_name }}
    steps:
      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4.4.0
        with:
          fetch-depth: 0
          ref: ${{ github.event_name == 'workflow_dispatch' && inputs.version_tag || github.ref }}
      - name: Validate version and tag
        shell: bash
        run: |
          set -euo pipefail
          ./scripts/verify-version.sh
          git show-ref --verify --quiet "refs/tags/${RELEASE_TAG}" || {
            echo "Release tag does not exist: ${RELEASE_TAG}" >&2
            exit 1
          }
          version=$(sed -n '1p' VERSION)
          if [ "${RELEASE_TAG}" != "v${version}" ]; then
            echo "Release tag ${RELEASE_TAG} does not match VERSION v${version}" >&2
            exit 1
          fi
          if [ "$(git rev-parse HEAD)" != "$(git rev-list -n 1 "${RELEASE_TAG}")" ]; then
            echo "Checked-out commit is not the commit referenced by ${RELEASE_TAG}" >&2
            exit 1
          fi
      - name: Build offline image
        run: ./scripts/package-offline.sh
      - name: Validate archive
        run: ./scripts/verify-offline.sh
      - name: Generate checksums
        shell: bash
        run: |
          cd release
          sha256sum "ai-admin-${RELEASE_TAG}.tar.gz" > SHA256SUMS
      - uses: softprops/action-gh-release@3bb12739c298aeb8a4eeaf626c5b8d85266b0e65 # v2.6.2
        with:
          tag_name: ${{ env.RELEASE_TAG }}
          name: ai-admin ${{ env.RELEASE_TAG }}
          generate_release_notes: true
          fail_on_unmatched_files: true
          files: |
            release/ai-admin-${{ env.RELEASE_TAG }}.tar.gz
            release/SHA256SUMS
