func (s *Server) oidcCallbackFailure(w http.ResponseWriter, r *http.Request, status int, code, message string, cause error) {
	stage := oidcFailureStage(code)
	reference := safeOIDCFailureReference(middleware.GetReqID(r.Context()))
	if cause != nil {
		s.logger.Warn("OIDC callback failed", "code", code, "stage", stage, "reference", reference, "error", cause)
	}
	s.audit(r, auth.Principal{}, "auth.login", "session", "", "failure", map[string]any{"source": "oidc", "reason": code, "stage": stage})
	if oidcWantsJSON(r) {
		writeError(w, status, code, message, map[string]string{"stage": stage, "reference": reference})
		return
	}
	query := url.Values{}
	query.Set("oidc_error", code)
	query.Set("oidc_error_description", message)
	query.Set("oidc_error_stage", stage)
	if reference != "" {
		query.Set("oidc_error_reference", reference)
	}
	w.Header().Set("Cache-Control", "no-store")
	http.Redirect(w, r, "/login?"+query.Encode(), http.StatusSeeOther)
}

func safeOIDCFailureReference(raw string) string {
	value := truncateRunes(strings.TrimSpace(raw), requestIDMaximum)
	if value == "" || !safeReferenceRunes(value) {
		return ""
	}
	return value
}

