type sessionCredentials struct {
	cookies []*http.Cookie
	csrf    string
}

func signIn(t *testing.T, handler http.Handler) sessionCredentials {
	t.Helper()
	login := loginRequest(t, handler, "integration-password", "trace-db-error", "Go-Test")
	if login.Code != http.StatusOK {
		t.Fatalf("login status=%d body=%s", login.Code, login.Body.String())
	}
	credentials := sessionCredentials{cookies: login.Result().Cookies()}
	for _, cookie := range credentials.cookies {
		if cookie.Name == "ai_admin_csrf" {
			credentials.csrf = cookie.Value
		}
	}
	if credentials.csrf == "" {
		t.Fatal("login did not issue a CSRF cookie")
	}
	return credentials
}

func (c sessionCredentials) do(t *testing.T, handler http.Handler, method, target string, body any) *httptest.ResponseRecorder {
	t.Helper()
	var reader io.Reader
	if body != nil {
		raw, err := json.Marshal(body)
		if err != nil {
			t.Fatal(err)
		}
		reader = bytes.NewReader(raw)
	}
	request := httptest.NewRequest(method, target, reader)
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("X-CSRF-Token", c.csrf)
	for _, cookie := range c.cookies {
		request.AddCookie(cookie)
	}
	recorder := httptest.NewRecorder()
	handler.ServeHTTP(recorder, request)
	return recorder
}

